"""Local JSON API + static files for AgriContract (127.0.0.1 only)."""
import argparse
import json
import mimetypes
import secrets
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse, parse_qs

import chat
import contracts
import db
import flags
import geo
import photos
import registry
from contracts import Conflict, Forbidden

ROOT = Path(__file__).resolve().parent
STATIC = ROOT / 'static'
DEFAULT_DB = ROOT / 'data' / 'contract.sqlite3'
CSP = "default-src 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'"
CSP_PRINT = CSP.replace("script-src 'self'", "script-src 'self' 'unsafe-inline'")
NOTE_KM = 'CDB បង្ហាញតែចំនួនសរុបរបស់ឃុំ មិនអាចបញ្ជាក់ចម្ការណាមួយបានទេ។'
NOTE_EN = "CDB shows commune totals; it can't confirm any one plot."


class Unauthorized(Exception):
    pass


class Locked(Exception):
    pass


class Raw:
    """Bytes to send as they are (a photo), not as JSON."""
    def __init__(self, data, mime):
        self.data, self.mime = bytes(data), mime


MAX_FAILS, LOCK_MINUTES = 5, 10   # wrong passwords in a row before a username is locked, and for how long


# --- builders ---------------------------------------------------------------
def coop_flags(conn, coop_id):
    g = geo.load()
    org = db.get_org(conn, coop_id)
    members, source = contracts.supply(conn, coop_id)
    reg = registry.get(org['ac_id']) if org['ac_id'] else None
    real = [m for m in members if not m.get('rest')]   # the 'not entered yet' MAFF line is not a farmer to check
    return flags.member_flags(real, g.communes, g.districts, reg), members, reg, source


def verify(conn, org, reg):
    """The 2-step check, plus: a co-op that claimed a MAFF record itself is only "claimed" until a processor signs with it."""
    v = flags.verify(reg, geo.load().communes)
    v['claimed'] = bool(reg and org['signup'] and not conn.execute(
        "select 1 from contracts where coop_id=? and status='signed'", (org['id'],)).fetchone())
    return v


def reg_public(reg, org):
    """Registry facts for display; a demo co-op shown under a made-up name never shows its real one."""
    if not reg:
        return None
    return {k: v for k, v in reg.items() if not (org['anon'] and k in ('name_kh', 'village_kh'))}


def by_variety(members):
    out = {}
    for m in members:
        v = out.setdefault(m['variety'], dict(variety=m['variety'], members=0, ha=0.0, expected_kg=0.0))
        v['members'] += 1
        v['ha'] += m['ha'] or 0
        v['expected_kg'] += m['expected_kg'] or 0
    return sorted(out.values(), key=lambda v: -v['expected_kg'])


def org_public(org):
    out = {k: org[k] for k in ('id', 'type', 'name_kh', 'name_en', 'reg_no', 'pv_code', 'ds_code', 'cm_code',
                               'village', 'ac_id', 'facebook_url', 'anon')}
    out['harvest_from'], out['harvest_to'] = org.get('harvest_from'), org.get('harvest_to')
    if org['anon']:
        out['facebook_url'] = ''
    return out


def place(org):
    g = geo.load()
    c, d = g.commune(org.get('cm_code')), g.district(org.get('ds_code'))
    p = g.provinces.get(org.get('pv_code'))
    return dict(commune=c and c['name_kh'], district=d and d['name_kh'], province=p and p['name_kh'],
                commune_en=c and c['name_en'], district_en=d and d['name_en'], province_en=p and p['name_en'])


def coop_card(conn, coop_id, viewer):
    org = db.get_org(conn, coop_id)
    if not org or org['type'] != 'coop':
        raise LookupError(coop_id)
    fl, members, reg, source = coop_flags(conn, coop_id)
    real = [m for m in members if m['id']]
    mine = [c for c in contracts.list_for(conn, viewer) if c['coop_id'] == coop_id] if viewer['role'] == 'processor' else []
    head = max(len(real), (reg and reg['members_total']) or 0) if source in ('maff', 'mixed') else len(real)
    rest = next((m for m in members if m.get('rest')), None)
    return dict(org=org_public(org), place=place(org), registry=reg_public(reg, org), flags=fl,
                verify=verify(conn, org, reg), note_km=NOTE_KM, note_en=NOTE_EN,
                totals=dict(members=head or 0, ha=round(sum(m['ha'] or 0 for m in members), 2),
                            expected_kg=round(sum(m['expected_kg'] or 0 for m in members)),
                            owes=sum(m['owes_at_harvest'] for m in members), source=source, entered=len(real),
                            rest_kg=round(rest['expected_kg']) if rest else 0),
                by_variety=by_variety(real), contracts=mine, deliveries=[], photos=photos.list_for(conn, coop_id),
                can_message=viewer['role'] == 'processor')


def signup_search(conn, q):
    """MAFF records a new co-op can claim. Records held by a hidden-name demo co-op are left out, so the
    demo never shows which real co-op it is; records held by anyone else show as taken."""
    out = []
    for r in registry.search(q, limit=15):
        org = db.claimed_by(conn, r['ac_id'])
        if org and org['anon']:
            continue
        out.append({k: r[k] for k in ('ac_id', 'name_kh', 'commune_kh', 'district_kh', 'province_kh',
                                      'members_total', 'has_cashew', 'cashew_ha')} | {'taken': bool(org)})
    return out


def check_status(v):
    """One word for the 2-step check: pass (both green), claimed (self-picked MAFF record, not yet confirmed),
    over (MAFF land above CDB), no_maff, or unknown (in MAFF, but step 2 can't run)."""
    if not v['maff']:
        return 'no_maff'
    if v['claimed']:
        return 'claimed'
    return {'ok': 'pass', 'over': 'over'}.get(v['land']['status'], 'unknown')


def check_steps(v):
    """The two steps one by one, for the badges on each row of the co-op list.
    step1: yes (in MAFF) / claimed (picked its MAFF record itself, not confirmed yet) / no.
    step2: ok (MAFF land fits CDB) / over (MAFF land above the whole commune in CDB) / na (can't check)."""
    step1 = 'no' if not v['maff'] else ('claimed' if v['claimed'] else 'yes')
    step2 = v['land']['status'] if v['maff'] and v['land']['status'] in ('ok', 'over') else 'na'
    return dict(step1=step1, step2=step2)


def find_coops(conn, viewer, q):
    """The processor's search: co-ops on the app, filtered, most tonnes first. "New" = no contract with this
    processor yet, which is the point of the app (finding co-ops it doesn't already know).

    q: pv (province code), variety, min_t (tonnes of that variety, or of all), checked=1 (both checks green),
    new=1. Also counts MAFF cashew co-ops that aren't on the app yet (a number only, never names)."""
    one = lambda k: (q.get(k) or [''])[0] if isinstance(q.get(k), list) else str(q.get(k) or '')
    pv, variety, checked, new_only = one('pv'), one('variety'), one('checked') == '1', one('new') == '1'
    if variety and variety not in db.VARIETIES:
        raise ValueError('variety')
    min_t = float(one('min_t') or 0)
    if min_t < 0:
        raise ValueError('min_t')
    known = {r['coop_id'] for r in conn.execute('select distinct coop_id from contracts where processor_id=?', (viewer['org_id'],))}
    results, unlisted, on_app = [], 0, set()
    for o in conn.execute("select id, ac_id from orgs where type='coop'").fetchall():
        if o['ac_id']:
            on_app.add(o['ac_id'])
        k = coop_card(conn, o['id'], viewer)
        if pv and k['org']['pv_code'] != pv:
            continue
        rows = k['by_variety']
        if variety:
            if not rows:
                unlisted += 1
                continue
            rows = [r for r in rows if r['variety'] == variety]
            if not rows:
                continue
            tonnes = rows[0]['expected_kg'] / 1000
        else:
            tonnes = k['totals']['expected_kg'] / 1000
        status = check_status(k['verify'])
        row = dict(org=k['org'], place=k['place'], tonnes=round(tonnes, 1), members=k['totals']['members'],
                   source=k['totals']['source'], varieties=[r['variety'] for r in k['by_variety']], check=status,
                   steps=check_steps(k['verify']), photos=len(k['photos']),
                   new=o['id'] not in known, red=sum(f['level'] == 'red' for f in k['flags']),
                   amber=sum(f['level'] == 'amber' for f in k['flags']))
        if tonnes < min_t or (checked and status != 'pass') or (new_only and not row['new']):
            continue
        results.append(row)
    results.sort(key=lambda r: (-r['tonnes'], r['org']['name_kh']))
    not_on_app = sum(1 for r in registry.rows() if r['has_cashew'] and r['ac_id'] not in on_app and (not pv or r['pv_code'] == pv))
    return dict(results=results, unlisted=unlisted, not_on_app=not_on_app)


def signup(conn, b):
    """A co-op or a processor makes its own account. A co-op claims a MAFF record (location comes from MAFF)
    or types a name and commune; a processor types its company name and province."""
    pin, who = str(b.get('pin') or ''), str(b.get('user_name') or '').strip()[:60]
    if not (len(pin) == 4 and pin.isdigit()):
        raise ValueError('pin')
    if not who:
        raise ValueError('user_name')
    login = dict(username=db.clean_username(b.get('username')), password=db.clean_password(b.get('password')))
    if db.username_taken(conn, login['username']):
        raise ValueError('username_taken')
    kind = str(b.get('type') or 'coop')
    if kind not in ('coop', 'processor'):
        raise ValueError('type')
    ac = str(b.get('ac_id') or '') if kind == 'coop' else ''
    conn.execute('begin immediate')
    try:
        if kind == 'processor':
            name, pv = str(b.get('name_kh') or '').strip()[:80], str(b.get('pv_code') or '')
            if not name:
                raise ValueError('name_kh')
            if pv not in geo.load().provinces:
                raise ValueError('pv_code')
            org = db.create_org(conn, 'processor', signup=True, name_kh=name, name_en=str(b.get('name_en') or '').strip()[:80], pv_code=pv)
            u = db.create_user(conn, 'processor', org, who, pin, **login)
            db.log(conn, u, 'org', org, 'signup', {'type': 'processor'})
            conn.execute('commit')
            return u
        if ac:
            reg = registry.get(ac)
            if not reg:
                raise ValueError('ac_id')
            if db.claimed_by(conn, ac):
                raise contracts.Conflict('taken')
            fields = dict(name_kh=reg['name_kh'], pv_code=reg['pv_code'], ds_code=reg['ds_code'], cm_code=reg['cm_code'], ac_id=ac)
        else:
            name, c = str(b.get('name_kh') or '').strip()[:80], geo.load().commune(str(b.get('cm_code') or ''))
            if not name:
                raise ValueError('name_kh')
            if not c:
                raise ValueError('cm_code')
            fields = dict(name_kh=name, pv_code=c['pv_code'], ds_code=c['ds_code'], cm_code=c['code'])
        org = db.create_org(conn, 'coop', signup=True, **fields)
        u = db.create_user(conn, 'coop', org, who, pin, **login)
        db.log(conn, u, 'org', org, 'signup', {'ac_id': ac})
        conn.execute('commit')
    except BaseException:
        conn.execute('rollback')
        raise
    return u


def contract_view(conn, c):
    g = geo.load()
    members, _ = contracts.supply(conn, c['coop_id'])
    out = dict(c, processor=org_public(db.get_org(conn, c['processor_id'])), coop=org_public(db.get_org(conn, c['coop_id'])))
    out['varieties'] = c['varieties'].split(',')
    out['signatures'] = signatures(c)
    out.pop('terms_hash', None)
    out['flags'] = flags.contract_flags(c['estimate_t'], members, g.communes)
    out['live_estimate_t'] = contracts.estimate_t(c['share_pct'], members)
    return out


def print_contract(conn, c):
    p, k = db.get_org(conn, c['processor_id']), db.get_org(conn, c['coop_id'])
    return dict(ref=c['ref'], processor=dict(name=p['name_kh'], name_en=p['name_en'] or '', registration_no=p['reg_no'] or '__________'),
                coop=dict(name=k['name_kh'], name_en=k['name_en'] or '', registration_no=k['reg_no'] or '__________'), season=c['season'],
                varieties=c['varieties'].split(','), share_pct=c['share_pct'], estimate_t=c['estimate_t'],
                moisture_max_pct=c['moisture_max'], outturn_min_pct=c['outturn_min'], foreign_matter_max_pct=c['foreign_max'],
                floor_riel_per_kg=c['floor_riel'], fail_discount_riel_per_kg=c['fail_discount_riel'],
                payment_days=c['pay_days'], mediator=c['mediator'],
                deliver_from=c.get('deliver_from'), deliver_to=c.get('deliver_to'),
                signatures=signatures(c),
                verify=dict(ref=c['ref'], key=c['verify_key']) if c['status'] == 'signed' and c.get('verify_key') else None)


def signatures(c):
    """Who signed in the app and when; the code identifies the exact terms they signed."""
    return dict(processor=dict(by=c['proc_sign_by'], at=c['proc_sign_at']), coop=dict(by=c['coop_sign_by'], at=c['coop_sign_at']),
                code=contracts.sign_code(c['terms_hash']) if c['proc_sign_at'] else '')


def verify_page(conn, c):
    """Public answer for a scanned verify QR: is this contract real and still valid, and the key terms."""
    p, k = db.get_org(conn, c['processor_id']), db.get_org(conn, c['coop_id'])
    _, _, reg, _ = coop_flags(conn, c['coop_id'])
    return dict(status=contracts.verify_status(c), ref=c['ref'], checked_at=db.now(),
                processor=p['name_kh'], coop=k['name_kh'], season=c['season'], varieties=c['varieties'].split(','),
                estimate_t=c['estimate_t'], floor_riel=c['floor_riel'], pay_days=c['pay_days'],
                deliver_from=c.get('deliver_from'), deliver_to=c.get('deliver_to'),
                signatures=signatures(c), check=verify(conn, k, reg))


def print_bankpack(conn, c):
    _, _, reg, _ = coop_flags(conn, c['coop_id'])
    groups = {}
    for m in db.list_members(conn, c['coop_id']):
        groups.setdefault(m['variety'], []).append(dict(name=m['name'], village=m['village'], ha=m['ha'] or 0,
                                                        expected_kg=m['expected_kg'] or 0))
    return dict(contract=print_contract(conn, c),
                members_by_variety=[dict(variety=v, members=ms) for v, ms in groups.items()],
                check=verify(conn, db.get_org(conn, c['coop_id']), reg),
                registry=dict(registered=bool(reg), source=registry.SOURCE,
                              members_total=reg and reg['members_total'], cashew_ha=reg and reg['cashew_ha'],
                              cashew_t=reg and reg['cashew_t']))


def home(conn, user):
    cs = [c for c in contracts.list_for(conn, user) if c['status'] != 'declined']
    # A co-op's next job is answering an offer, so a waiting offer comes before a signed contract.
    rank = {'offered': 0, 'signed': 1} if user['role'] == 'coop' else {'signed': 0, 'offered': 1, 'draft': 2}
    active = min(cs, key=lambda c: (rank.get(c['status'], 9), -c['id'])) if cs else None
    if active:
        active = dict(active, other=org_public(db.get_org(conn, active['coop_id' if user['role'] == 'processor' else 'processor_id'])))
    return dict(user=user, org=org_public(db.get_org(conn, user['org_id'])), active=active, season=contracts.season_now(),
                counts=dict(contracts=len(cs), waiting=sum(c['status'] == 'offered' for c in cs), unread=chat.unread(conn, user)),
                activity=db.recent_events(conn, user['org_id']))


# --- HTTP -------------------------------------------------------------------
class App:
    def __init__(self, db_path):
        self.conn = db.connect(str(db_path))
        self.sessions = {}
        self.fails = {}   # username -> (wrong tries in a row, locked until)
        self._lock = threading.Lock()

    def locked(self, name, now=None):
        with self._lock:
            _, until = self.fails.get(name, (0, 0))
            return until > (now or time.time())

    def failed(self, name, now=None):
        with self._lock:
            n, _ = self.fails.get(name, (0, 0))
            n += 1
            self.fails[name] = (0, (now or time.time()) + LOCK_MINUTES * 60) if n >= MAX_FAILS else (n, 0)


class Handler(BaseHTTPRequestHandler):
    app = None
    server_version = 'AgriContract/1'

    def log_message(self, *a):
        pass

    # helpers
    def send(self, code, body, ctype='application/json; charset=utf-8', extra=None):
        data = body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False, default=str).encode()
        self.send_response(code)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Security-Policy', CSP_PRINT if self.path.startswith('/print/') else CSP)
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(data)

    def body(self):
        n = int(self.headers.get('Content-Length') or 0)
        if n > 100_000:
            raise ValueError('too large')
        return json.loads(self.rfile.read(n) or b'{}') if n else {}

    def raw_body(self, limit):
        n = int(self.headers.get('Content-Length') or 0)
        if n > limit:
            # read and drop what was sent (up to 20 MB) so the phone gets a clear "too large" answer
            left = min(n, 20_000_000)
            while left > 0:
                got = self.rfile.read(min(left, 65536))
                if not got:
                    break
                left -= len(got)
            if n > 20_000_000:
                self.close_connection = True
            raise ValueError('too_large')
        return self.rfile.read(n) if n else b''

    def user(self):
        for part in (self.headers.get('Cookie') or '').split(';'):
            k, _, v = part.strip().partition('=')
            if k == 'sid' and v in self.app.sessions:
                return self.app.sessions[v]
        raise Unauthorized()

    def need(self, role):
        u = self.user()
        if u['role'] != role:
            raise Forbidden()
        return u

    def do_GET(self):
        self.route('GET')

    def do_POST(self):
        self.route('POST')

    def do_PUT(self):
        self.route('PUT')

    def do_DELETE(self):
        self.route('DELETE')

    def route(self, method):
        url = urlparse(self.path)
        parts = [p for p in url.path.split('/') if p]
        try:
            if parts[:1] != ['api']:
                if method != 'GET':
                    return self.send(405, {'error': 'method'})
                return self.static(url.path)
            # same-origin guard for writes
            # https covers the team link (Cloudflare tunnel); still the same host only
            host = self.headers.get('Host')
            if method != 'GET' and self.headers.get('Origin') not in (None, f'http://{host}', f'https://{host}'):
                raise Forbidden()
            res = self.api(method, parts[1:], parse_qs(url.query))
            if isinstance(res, Raw):
                return self.send(200, res.data, res.mime)
            if isinstance(res, tuple):
                return self.send(200, res[0], extra=res[1])
            return self.send(200, res)
        except Locked:
            self.send(429, {'error': 'locked', 'minutes': LOCK_MINUTES})
        except Unauthorized:
            self.send(401, {'error': 'login'})
        except Forbidden:
            self.send(403, {'error': 'forbidden'})
        except LookupError:
            self.send(404, {'error': 'not_found'})
        except Conflict as e:
            self.send(409, {'error': 'conflict', 'status': str(e)})
        except (ValueError, KeyError, TypeError, json.JSONDecodeError) as e:
            self.send(400, {'error': 'invalid', 'field': str(e)})

    def start_session(self, u):
        sid = secrets.token_urlsafe(24)
        self.app.sessions[sid] = u
        return u, {'Set-Cookie': f'sid={sid}; HttpOnly; SameSite=Strict; Path=/'}

    def static(self, path):
        rel = 'index.html' if path in ('', '/') else path.lstrip('/')
        f = (STATIC / rel).resolve()
        if STATIC not in f.parents or not f.is_file():
            return self.send(404, {'error': 'not_found'})
        ctype = mimetypes.guess_type(f.name)[0] or 'application/octet-stream'
        if ctype.startswith('text/') or ctype in ('application/javascript', 'application/json'):
            ctype += '; charset=utf-8'
        self.send(200, f.read_bytes(), ctype)

    def api(self, method, p, q):
        conn = self.app.conn
        key = (method, *p[:1])
        if key == ('POST', 'login'):
            b = self.body()
            name = str(b.get('username') or '').strip().lower()[:24]
            if self.app.locked(name):
                raise Locked()
            u = db.check_login(conn, name, b.get('password'))
            if not u:
                self.app.failed(name)
                raise Unauthorized()
            self.app.fails.pop(name, None)
            return self.start_session(u)
        if key == ('GET', 'signup') and p[1:] == ['registry']:
            return signup_search(conn, (q.get('q') or [''])[0])
        if key == ('POST', 'signup'):
            return self.start_session(signup(conn, self.body()))
        if key == ('POST', 'logout'):
            for part in (self.headers.get('Cookie') or '').split(';'):
                k, _, v = part.strip().partition('=')
                if k == 'sid':
                    self.app.sessions.pop(v, None)
            return {'ok': True}, {'Set-Cookie': 'sid=; Max-Age=0; Path=/'}
        if key == ('GET', 'verify'):   # public: a bank scans the QR on a printed contract, no login
            c = contracts.find_by_key(conn, (q.get('r') or [''])[0], (q.get('k') or [''])[0])
            if not c:
                raise LookupError('verify')
            return verify_page(conn, c)
        if key == ('GET', 'geo'):
            return geo.load().catalog()
        if key == ('GET', 'varieties'):
            return flags.VARIETIES
        u = self.user()
        if key == ('GET', 'me'):
            return u
        if key == ('GET', 'home'):
            return home(conn, u)
        if key == ('GET', 'registry'):
            return registry.search((q.get('q') or [''])[0])
        if p[0] == 'coop':  # /api/coop/profile, /api/coop/flags
            u = self.need('coop')
            if p[1:] == ['profile'] and method == 'GET':
                return coop_card(conn, u['org_id'], u)
            if p[1:2] == ['photos'] and len(p) == 2 and method == 'POST':
                caption = (q.get('caption') or [''])[0]
                return photos.add(conn, u['org_id'], self.raw_body(photos.MAX_BYTES), caption, u)
            if p[1:2] == ['photos'] and len(p) == 3 and method == 'DELETE':
                photos.delete(conn, u['org_id'], int(p[2]))
                return {'ok': True}
            if p[1:] == ['profile'] and method == 'PUT':
                b = self.body()
                if b.get('ac_id') and not registry.get(b['ac_id']):
                    raise ValueError('ac_id')
                other = db.claimed_by(conn, b.get('ac_id'))
                if other and other['id'] != u['org_id']:
                    raise Conflict('taken')
                if db.get_org(conn, u['org_id'])['anon'] and ({'ac_id', 'facebook_url'} & set(b)):
                    raise ValueError('name_hidden')
                if 'harvest_from' in b or 'harvest_to' in b:
                    db.set_harvest(conn, u['org_id'], b.get('harvest_from'), b.get('harvest_to'), u)
                db.update_org(conn, u['org_id'], b, u)
                return coop_card(conn, u['org_id'], u)
        if p[0] == 'members':
            u = self.need('coop')
            if len(p) == 1 and method == 'GET':
                return coop_card(conn, u['org_id'], u) | {'members': db.list_members(conn, u['org_id'])}
            if len(p) == 1 and method == 'POST':
                return db.add_member(conn, u['org_id'], self.body(), u)
            if len(p) == 2 and method == 'PUT':
                return db.update_member(conn, u['org_id'], int(p[1]), self.body(), u)
            if len(p) == 2 and method == 'DELETE':
                db.delete_member(conn, u['org_id'], int(p[1]), u)
                return {'ok': True}
        if p[0] == 'photos' and len(p) == 2 and method == 'GET':
            # processors browsing co-ops, or the co-op itself
            ph = photos.get(conn, int(p[1]))
            if u['role'] != 'processor' and u['org_id'] != ph['coop_id']:
                raise Forbidden()
            return Raw(ph['data'], ph['mime'])
        if p[0] == 'messages':
            if len(p) == 1 and method == 'GET':
                rows = chat.inbox(conn, u)
                return [dict(r, other=org_public(db.get_org(conn, r['other_id']))) for r in rows]
            other = int(p[1])
            if len(p) == 2 and method == 'GET':
                msgs = chat.thread(conn, u, other)
                return dict(other=org_public(db.get_org(conn, other)), messages=msgs, can_write=chat.can_write(conn, u, other))
            if len(p) == 2 and method == 'POST':
                return chat.send(conn, u, other, self.body().get('body'))
        if p[0] == 'find' and method == 'GET':
            return find_coops(conn, self.need('processor'), q)
        if p[0] == 'coops':
            u = self.need('processor')
            if len(p) == 1:
                coops = conn.execute("select id from orgs where type='coop' order by name_kh").fetchall()
                return [coop_card(conn, c['id'], u) for c in coops]
            return coop_card(conn, int(p[1]), u)
        if p[0] == 'contracts':
            if len(p) == 1 and method == 'GET':
                return [contract_view(conn, c) for c in contracts.list_for(conn, u)]
            if len(p) == 1 and method == 'POST':
                return contract_view(conn, contracts.create(conn, u, self.body()))
            cid = int(p[1])
            if len(p) == 2 and method == 'GET':
                return contract_view(conn, contracts.get(conn, cid, u))
            if len(p) == 2 and method == 'PUT':
                return contract_view(conn, contracts.update_terms(conn, cid, self.body(), u))
            if len(p) == 3 and method == 'POST':
                b = self.body()
                return contract_view(conn, contracts.transition(conn, cid, p[2], u, pin=b.get('pin'),
                                                                reason=b.get('reason', '')))
        if p[0] == 'print' and method == 'GET':
            if p[1:] == ['pledge']:
                u = self.need('coop')
                org = db.get_org(conn, u['org_id'])
                latest = next(iter(contracts.list_for(conn, u)), None)
                return dict(coop_name=org['name_kh'], season=latest['season'] if latest else contracts.season_now(),
                            members=[dict(name=m['name'], village=m['village'], variety=m['variety'], ha=m['ha'] or 0,
                                          expected_kg=m['expected_kg'] or 0) for m in db.list_members(conn, u['org_id'])])
            c = contracts.get(conn, int(p[2]), u)
            if p[1] == 'contract':
                return print_contract(conn, c)
            if p[1] == 'bankpack':
                return print_bankpack(conn, c)
        raise LookupError(self.path)


def make_server(db_path=DEFAULT_DB, port=5186):
    Handler.app = App(db_path)
    return ThreadingHTTPServer(('127.0.0.1', port), Handler)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--db', default=str(DEFAULT_DB))
    ap.add_argument('--port', type=int, default=5186)
    a = ap.parse_args()
    srv = make_server(a.db, a.port)
    print(f'AgriContract on http://127.0.0.1:{a.port}', flush=True)
    srv.serve_forever()


if __name__ == '__main__':
    main()

