"""SQLite storage: orgs, users (PIN), members, contracts, events."""
import hashlib
import re
import hmac
import secrets
import json
import os
import sqlite3
from datetime import datetime, timezone

VARIETIES = ('M23', 'H09', 'M10', 'IM4', 'Other')

SCHEMA = '''
create table if not exists orgs(id integer primary key, type text not null check(type in ('processor','coop')),
  name_kh text not null, name_en text default '', reg_no text default '', pv_code text default '', ds_code text default '',
  cm_code text default '', village text default '', ac_id text default '', facebook_url text default '', anon integer not null default 0,
  signup integer not null default 0);
create table if not exists users(id integer primary key, role text not null, org_id integer not null references orgs(id),
  name text not null, pin_salt blob not null, pin_hash blob not null);
create table if not exists members(id integer primary key, coop_id integer not null references orgs(id), name text not null,
  village text default '', cm_code text default '', ds_code text default '', pv_code text default '',
  variety text not null, ha real not null default 0, tree_age integer, expected_kg real, owes_at_harvest integer not null default 0);
create table if not exists contracts(id integer primary key, ref text unique, processor_id integer not null references orgs(id),
  coop_id integer not null references orgs(id), season text not null, varieties text not null, share_pct real not null,
  estimate_t real not null, moisture_max real not null, outturn_min real not null, foreign_max real not null,
  floor_riel integer not null, fail_discount_riel integer not null, pay_days integer not null, mediator text not null,
  status text not null, paper_date text, paper_by text, decline_reason text default '', created_at text, updated_at text,
  terms_hash text, proc_sign_at text, proc_sign_by text, coop_sign_at text, coop_sign_by text);
create table if not exists events(id integer primary key, ts text not null, user_id integer, org_id integer,
  entity text not null, entity_id integer, action text not null, detail text default '{}');
create table if not exists photos(id integer primary key, coop_id integer not null references orgs(id),
  caption text default '', mime text not null, data blob not null, created_at text not null, user_id integer);
create table if not exists messages(id integer primary key, processor_id integer not null references orgs(id),
  coop_id integer not null references orgs(id), from_org integer not null, user_id integer, body text not null,
  created_at text not null, read_at text);
create index if not exists messages_pair on messages(processor_id, coop_id, id);
'''


def now():
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


def connect(path):
    if path != ':memory:':
        os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    conn = sqlite3.connect(path, check_same_thread=False, isolation_level=None)
    conn.row_factory = lambda cur, row: {d[0]: row[i] for i, d in enumerate(cur.description)}
    conn.execute('pragma foreign_keys=on')
    conn.executescript(SCHEMA)
    have = {c['name'] for c in conn.execute('pragma table_info(contracts)').fetchall()}
    for col in ('terms_hash', 'proc_sign_at', 'proc_sign_by', 'coop_sign_at', 'coop_sign_by', 'deliver_from', 'deliver_to',
                'verify_key'):
        if col not in have:
            conn.execute(f'alter table contracts add column {col} text')
    if 'signup' not in {c['name'] for c in conn.execute('pragma table_info(orgs)').fetchall()}:
        conn.execute('alter table orgs add column signup integer not null default 0')
    if 'anon' not in {c['name'] for c in conn.execute('pragma table_info(orgs)').fetchall()}:
        conn.execute('alter table orgs add column anon integer not null default 0')
    ocols = {c['name'] for c in conn.execute('pragma table_info(orgs)').fetchall()}
    for col in ('harvest_from', 'harvest_to'):          # the co-op's usual harvest months, 1-12
        if col not in ocols:
            conn.execute(f'alter table orgs add column {col} integer')
    ucols = {c['name'] for c in conn.execute('pragma table_info(users)').fetchall()}
    for col, kind in (('username', 'text'), ('pw_salt', 'blob'), ('pw_hash', 'blob')):
        if col not in ucols:
            conn.execute(f'alter table users add column {col} {kind}')
    conn.execute('create unique index if not exists users_username on users(username)')
    # contracts signed before the verify QR existed get their secret key now
    for row in conn.execute("select id from contracts where status='signed' and verify_key is null").fetchall():
        conn.execute('update contracts set verify_key=? where id=?', (new_verify_key(), row['id']))
    return conn


def new_verify_key():
    """The secret in a contract's verify QR: without it nobody can look a contract up by guessing its reference."""
    return secrets.token_urlsafe(12)


def log(conn, user, entity, entity_id, action, detail=None):
    conn.execute('insert into events(ts,user_id,org_id,entity,entity_id,action,detail) values(?,?,?,?,?,?,?)',
                 (now(), user and user['id'], user and user['org_id'], entity, entity_id, action,
                  json.dumps(detail or {}, ensure_ascii=False)))


# orgs and users -----------------------------------------------------------
ORG_FIELDS = ('name_kh', 'name_en', 'reg_no', 'pv_code', 'ds_code', 'cm_code', 'village', 'ac_id', 'facebook_url')


def create_org(conn, type_, anon=False, signup=False, **fields):
    """anon=True: a real registry co-op shown under a made-up name (demo only). signup=True: the co-op made its own account."""
    f = {k: str(fields.get(k) or '') for k in ORG_FIELDS}
    cur = conn.execute(f'insert into orgs(type,anon,signup,{",".join(ORG_FIELDS)}) values(?,?,?{",?" * len(ORG_FIELDS)})',
                       (type_, int(bool(anon)), int(bool(signup)), *f.values()))
    return cur.lastrowid


def claimed_by(conn, ac_id):
    """The org that already holds this MAFF record, if any: one record, one account."""
    return conn.execute("select * from orgs where ac_id=? and ac_id!=''", (ac_id,)).fetchone() if ac_id else None


def get_org(conn, org_id):
    return conn.execute('select * from orgs where id=?', (org_id,)).fetchone()


def update_org(conn, org_id, fields, user):
    f = {k: str(v or '').strip() for k, v in fields.items() if k in ORG_FIELDS}
    if not f.get('name_kh', 'x'):
        del f['name_kh']
    url = f.get('facebook_url')
    if url and not url.startswith(('https://www.facebook.com/', 'https://facebook.com/', 'https://m.facebook.com/', 'https://fb.com/')):
        raise ValueError('facebook_url')
    if f:
        conn.execute(f'update orgs set {",".join(k + "=?" for k in f)} where id=?', (*f.values(), org_id))
        log(conn, user, 'org', org_id, 'update', {k: f[k] for k in f})
    return get_org(conn, org_id)


def set_harvest(conn, org_id, frm, to, user=None):
    """The co-op's usual harvest months (1-12; Dec-Mar style ranges allowed). Both empty clears them."""
    if frm in (None, '') and to in (None, ''):
        frm = to = None
    else:
        frm, to = int(frm), int(to)
        if not (1 <= frm <= 12 and 1 <= to <= 12):
            raise ValueError('harvest')
    conn.execute('update orgs set harvest_from=?, harvest_to=? where id=?', (frm, to, org_id))
    if user:
        log(conn, user, 'org', org_id, 'update', {'harvest_from': frm, 'harvest_to': to})


def _hash(pin, salt):
    return hashlib.pbkdf2_hmac('sha256', str(pin).encode(), salt, 200_000)


USERNAME = re.compile(r'^[a-z0-9][a-z0-9._-]{2,23}$')


def clean_username(name):
    """Usernames are 3-24 lower-case letters, digits, '.', '_' or '-', starting with a letter or digit."""
    name = str(name or '').strip().lower()
    if not USERNAME.match(name):
        raise ValueError('username')
    return name


def clean_password(pw):
    pw = str(pw or '')
    if not 6 <= len(pw) <= 64:
        raise ValueError('password')
    return pw


def create_user(conn, role, org_id, name, pin, username=None, password=None):
    """`pin` (4 digits) signs contracts; `username` + `password` log in. A user with no username cannot log in."""
    salt = os.urandom(16)
    login = {}
    if username is not None:
        login = dict(username=clean_username(username), pw_salt=os.urandom(16))
        login['pw_hash'] = _hash(clean_password(password), login['pw_salt'])
        if username_taken(conn, login['username']):
            raise ValueError('username_taken')
    cols = dict(role=role, org_id=org_id, name=name, pin_salt=salt, pin_hash=_hash(pin, salt), **login)
    cur = conn.execute(f"insert into users({','.join(cols)}) values({','.join('?' * len(cols))})", tuple(cols.values()))
    return dict(id=cur.lastrowid, role=role, org_id=org_id, name=name)


def set_login(conn, user_id, username, password):
    """Give an existing user a username and password (used to upgrade older demo databases)."""
    username, salt = clean_username(username), os.urandom(16)
    conn.execute('update users set username=?, pw_salt=?, pw_hash=? where id=?',
                 (username, salt, _hash(clean_password(password), salt), user_id))


def username_taken(conn, username):
    return conn.execute('select 1 from users where username=?', (str(username).strip().lower(),)).fetchone() is not None


def check_login(conn, username, password):
    u = conn.execute('select * from users where username=?', (str(username or '').strip().lower(),)).fetchone()
    if not u or not u['pw_hash'] or not hmac.compare_digest(u['pw_hash'], _hash(str(password or ''), u['pw_salt'])):
        return None
    return dict(id=u['id'], role=u['role'], org_id=u['org_id'], name=u['name'])


def check_pin(conn, user_id, pin):
    u = conn.execute('select * from users where id=?', (user_id,)).fetchone()
    if not u or not hmac.compare_digest(u['pin_hash'], _hash(pin, u['pin_salt'])):
        return None
    return dict(id=u['id'], role=u['role'], org_id=u['org_id'], name=u['name'])


# members ------------------------------------------------------------------
def _num(v, kind=float, allow_none=False):
    if v in (None, ''):
        return None if allow_none else kind(0)
    x = kind(float(v))
    if x < 0:
        raise ValueError('negative')
    return x


def clean_member(d):
    name = str(d.get('name') or '').strip()
    if not name:
        raise ValueError('name')
    v = str(d.get('variety') or '').strip().upper()
    variety = next((x for x in VARIETIES if x.upper() == v), None)
    if not variety:
        raise ValueError('variety')
    return dict(name=name[:80], village=str(d.get('village') or '').strip()[:80],
                cm_code=str(d.get('cm_code') or ''), ds_code=str(d.get('ds_code') or ''), pv_code=str(d.get('pv_code') or ''),
                variety=variety, ha=_num(d.get('ha')), tree_age=_num(d.get('tree_age'), int, True),
                expected_kg=_num(d.get('expected_kg'), float, True), owes_at_harvest=1 if d.get('owes_at_harvest') in (1, True, '1', 'yes', 'true') else 0)


def add_member(conn, coop_id, d, user=None):
    m = clean_member(d)
    cur = conn.execute(f'insert into members(coop_id,{",".join(m)}) values(?{",?" * len(m)})', (coop_id, *m.values()))
    log(conn, user, 'member', cur.lastrowid, 'add', {'name': m['name']})
    return get_member(conn, cur.lastrowid)


def get_member(conn, mid):
    return conn.execute('select * from members where id=?', (mid,)).fetchone()


def update_member(conn, coop_id, mid, d, user=None):
    old = get_member(conn, mid)
    if not old or old['coop_id'] != coop_id:
        raise LookupError(mid)
    m = clean_member({**old, **d})
    conn.execute(f'update members set {",".join(k + "=?" for k in m)} where id=?', (*m.values(), mid))
    log(conn, user, 'member', mid, 'update', {'name': m['name']})
    return get_member(conn, mid)


def delete_member(conn, coop_id, mid, user=None):
    old = get_member(conn, mid)
    if not old or old['coop_id'] != coop_id:
        raise LookupError(mid)
    conn.execute('delete from members where id=?', (mid,))
    log(conn, user, 'member', mid, 'delete', {'name': old['name']})


def list_members(conn, coop_id):
    return conn.execute('select * from members where coop_id=? order by name', (coop_id,)).fetchall()


# What the other side may see of a shared contract: what was sent and the answer, never drafts or draft edits.
SHARED_ACTIONS = ('offer', 'sign', 'decline')


def recent_events(conn, org_id, limit=12):
    """Own events, plus the other side's offer/sign/decline on our contracts, with the contract ref and the other party."""
    return conn.execute(f'''select e.*, u.name user_name, c.ref ref, o.name_kh other_kh, o.name_en other_en
        from events e left join users u on u.id=e.user_id
        left join contracts c on e.entity='contract' and c.id=e.entity_id
        left join orgs o on o.id = case when c.processor_id=? then c.coop_id else c.processor_id end
        where e.org_id=? or (e.entity='contract' and e.action in ({",".join("?" * len(SHARED_ACTIONS))})
                             and (c.processor_id=? or c.coop_id=?))
        order by e.id desc limit ?''', (org_id, org_id, *SHARED_ACTIONS, org_id, org_id, limit)).fetchall()

