"""The 7-box contract: terms, states and who may do what.

Signing is digital: the processor signs with its PIN when it sends the offer, the co-op signs with its PIN
when it agrees, and the contract is then signed. Each signature covers a hash of the terms."""
import hashlib
import hmac
import re
import json
from datetime import date

import db
import registry


class Conflict(Exception):
    pass


class Forbidden(Exception):
    pass


DEFAULTS = dict(varieties='M23', moisture_max=10, outturn_min=28, foreign_max=1,
                fail_discount_riel=300, pay_days=3, mediator='')   # empty = a mediator both sides agree on
LIMITS = dict(share_pct=(1, 100), moisture_max=(5, 20), outturn_min=(15, 40), foreign_max=(0, 10),
              floor_riel=(1000, 50000), fail_discount_riel=(0, 10000), pay_days=(0, 60), estimate_t=(0, 100000))
INTS = ('floor_riel', 'fail_discount_riel', 'pay_days')
TERMS = tuple(LIMITS) + ('season', 'varieties', 'mediator')
WINDOW = ('deliver_from', 'deliver_to')      # delivery months, 'YYYY-MM'
MONTH = re.compile(r'^(\d{4})-(0[1-9]|1[0-2])$')

# action: (who may do it, from-status, to-status); offer and sign need the user's PIN again.
FLOW = dict(offer=('processor', 'draft', 'offered'), sign=('coop', 'offered', 'signed'),
            decline=('coop', 'offered', 'declined'))
NEEDS_PIN = ('offer', 'sign')


def terms_hash(c):
    """What both signatures cover: the parties and every term. Any change gives a different hash."""
    body = {k: c[k] for k in ('ref', 'processor_id', 'coop_id', *TERMS)}
    for k in WINDOW:   # added later; left out when empty so contracts signed before still match
        if c.get(k):
            body[k] = c[k]
    return hashlib.sha256(json.dumps(body, sort_keys=True, ensure_ascii=False).encode()).hexdigest()


def sign_code(h):
    """Short code shown to both sides, e.g. 3F9A-21C0."""
    return f'{h[:4]}-{h[4:8]}'.upper() if h else ''


def estimate_t(share_pct, members):
    kg = sum(float(m.get('expected_kg') or 0) for m in members)
    return round(float(share_pct) / 100 * kg / 1000, 1)


def check_window(season, frm, to):
    """Delivery months: valid 'YYYY-MM', start not after end, at most 6 months, in the season (or the Dec/Nov before)."""
    a, b = MONTH.match(str(frm or '')), MONTH.match(str(to or ''))
    if not a or not b or frm > to:
        raise ValueError('deliver')
    span = (int(b[1]) - int(a[1])) * 12 + int(b[2]) - int(a[2])
    years = {int(str(season)[:4]) - 1, int(str(season)[:4])}
    if span > 5 or int(a[1]) not in years or int(b[1]) not in years:
        raise ValueError('deliver')


def default_window(org, season):
    """The co-op's usual harvest months if it set them, otherwise March to May (the main cashew harvest)."""
    y = int(str(season)[:4])
    a, b = org.get('harvest_from'), org.get('harvest_to')
    if a and b:
        return (f'{y - 1 if a > b else y}-{a:02d}', f'{y}-{b:02d}')
    return f'{y}-03', f'{y}-05'


def season_now(today=None):
    """The next harvest season: cashew is picked Feb–May, so from June on we are contracting for next year."""
    d = today or date.today()
    return str(d.year + 1 if d.month >= 6 else d.year)


def supply(conn, coop_id):
    """The co-op's supply lines: its members, plus, until all its farmers are in, the part of its MAFF record
    they don't cover yet (one 'rest' line). So adding the first farmer never drops a 200 t co-op to 2 t.

    Returns (rows, source): 'members', 'maff' (no farmers yet), 'mixed' (some farmers + rest of MAFF) or 'none'."""
    members = db.list_members(conn, coop_id)
    org = db.get_org(conn, coop_id)
    reg = registry.get(org['ac_id']) if org and org['ac_id'] else None
    if not (reg and reg['has_cashew'] and reg['cashew_ha']):
        return members, ('members' if members else 'none')
    maff_kg, maff_ha = (reg['cashew_t'] or 0) * 1000, reg['cashew_ha']
    kg = sum(m['expected_kg'] or 0 for m in members)
    all_in = bool(reg['members_total']) and len(members) >= reg['members_total']
    if members and (all_in or kg >= maff_kg):
        return members, 'members'
    line = dict(id=0, name='MAFF', cm_code=reg['cm_code'], ds_code=reg['ds_code'], pv_code=reg['pv_code'], variety='Other',
                ha=round(max(0.0, maff_ha - sum(m['ha'] or 0 for m in members)), 2), expected_kg=maff_kg - kg, owes_at_harvest=0)
    if not members:
        return [line], 'maff'
    return [*members, dict(line, rest=1)], 'mixed'


def _tonnes_to_share(conn, coop_id, fields):
    """The app asks for tonnes; the contract keeps the share of members' harvest behind it."""
    if fields.get('tonnes') in (None, ''):
        return fields
    t = float(fields['tonnes'])
    kg = sum(float(m.get('expected_kg') or 0) for m in supply(conn, coop_id)[0])
    if t <= 0 or kg <= 0 or t * 1000 > kg * 1.001:
        raise ValueError('tonnes')
    return {**fields, 'share_pct': min(100.0, round(t * 1000 / kg * 100, 2)), 'estimate_t': round(t, 1)}


def _clean(fields):
    out = {}
    for k, (lo, hi) in LIMITS.items():
        if k in fields and fields[k] not in (None, ''):
            v = float(fields[k])
            if not lo <= v <= hi:
                raise ValueError(k)
            out[k] = int(round(v)) if k in INTS else v
    if 'varieties' in fields:
        vs = fields['varieties']
        vs = vs.split(',') if isinstance(vs, str) else vs
        vs = [v for v in db.VARIETIES if v.upper() in {str(x).strip().upper() for x in vs}]
        if not vs:
            raise ValueError('varieties')
        out['varieties'] = ','.join(vs)
    for k in ('season', 'mediator'):
        if k in fields and str(fields[k]).strip():
            out[k] = str(fields[k]).strip()[:60]
    for k in WINDOW:
        if k in fields and str(fields[k] or '').strip():
            out[k] = str(fields[k]).strip()
    return out


def _party(c, user):
    if user['role'] == 'processor' and c['processor_id'] == user['org_id']:
        return 'processor'
    if user['role'] == 'coop' and c['coop_id'] == user['org_id'] and c['status'] != 'draft':
        return 'coop'
    raise Forbidden()


def get(conn, cid, user):
    c = conn.execute('select * from contracts where id=?', (cid,)).fetchone()
    if not c:
        raise LookupError(cid)
    _party(c, user)
    return c


def list_for(conn, user):
    if user['role'] == 'processor':
        return conn.execute('select * from contracts where processor_id=? order by id desc', (user['org_id'],)).fetchall()
    return conn.execute("select * from contracts where coop_id=? and status!='draft' order by id desc", (user['org_id'],)).fetchall()


def create(conn, user, fields):
    if user['role'] != 'processor':
        raise Forbidden()
    coop = db.get_org(conn, int(fields.get('coop_id') or 0))
    if not coop or coop['type'] != 'coop':
        raise ValueError('coop_id')
    fields = _tonnes_to_share(conn, coop['id'], fields)
    base = {**DEFAULTS, 'season': season_now()}
    t = {**base, **_clean({**base, **fields})}
    if 'floor_riel' not in t:
        raise ValueError('floor_riel')
    if not t.get('deliver_from') and not t.get('deliver_to'):
        t['deliver_from'], t['deliver_to'] = default_window(coop, t['season'])
    check_window(t['season'], t.get('deliver_from'), t.get('deliver_to'))
    t.setdefault('share_pct', 100.0)
    t.setdefault('estimate_t', estimate_t(t['share_pct'], supply(conn, coop['id'])[0]))
    ts = db.now()
    cur = conn.execute(f'insert into contracts(processor_id,coop_id,status,created_at,updated_at,{",".join(t)}) '
                       f'values(?,?,?,?,?{",?" * len(t)})', (user['org_id'], coop['id'], 'draft', ts, ts, *t.values()))
    cid = cur.lastrowid
    conn.execute('update contracts set ref=? where id=?', (f"C-{t['season'][:4]}-{cid:04d}", cid))
    db.log(conn, user, 'contract', cid, 'create')
    return get(conn, cid, user)


def update_terms(conn, cid, fields, user):
    c = get(conn, cid, user)
    if _party(c, user) != 'processor':
        raise Forbidden()
    if c['status'] not in ('draft', 'offered'):
        raise Conflict(c['status'])
    t = _clean(_tonnes_to_share(conn, c['coop_id'], fields))
    if 'share_pct' in t and 'estimate_t' not in t:
        t['estimate_t'] = estimate_t(t['share_pct'], supply(conn, c['coop_id'])[0])
    if set(WINDOW) & set(t):
        m = {**c, **t}
        check_window(m['season'], m.get('deliver_from'), m.get('deliver_to'))
    t = {k: v for k, v in t.items() if c.get(k) != v or k in ('status',)}   # only real changes void a signature
    if t and c['status'] == 'offered':
        # Changed terms void the processor's signature: back to draft, to be signed and sent again.
        t.update(status='draft', terms_hash=None, proc_sign_at=None, proc_sign_by=None)
    if t:
        conn.execute(f'update contracts set {",".join(k + "=?" for k in t)},updated_at=? where id=?', (*t.values(), db.now(), cid))
        db.log(conn, user, 'contract', cid, 'edit', {k: t[k] for k in t})
    return get(conn, cid, user)


def transition(conn, cid, action, user, pin=None, reason=''):
    if action not in FLOW:
        raise ValueError(action)
    who, frm, to = FLOW[action]
    conn.execute('begin immediate')
    try:
        c = get(conn, cid, user)
        if _party(c, user) != who:
            raise Forbidden()
        if c['status'] != frm:
            raise Conflict(c['status'])
        if action in NEEDS_PIN and not db.check_pin(conn, user['id'], str(pin or '')):
            raise ValueError('pin')
        extra, ts = {}, db.now()
        if action == 'offer':
            extra = dict(terms_hash=terms_hash(c), proc_sign_at=ts, proc_sign_by=user['name'])
        if action == 'sign':
            if c['terms_hash'] != terms_hash(c):
                raise Conflict('changed')
            extra = dict(coop_sign_at=ts, coop_sign_by=user['name'], verify_key=db.new_verify_key())
        if action == 'decline':
            extra = dict(decline_reason=str(reason)[:200])
        sets = ''.join(f',{k}=?' for k in extra)
        conn.execute(f'update contracts set status=?,updated_at=?{sets} where id=?', (to, ts, *extra.values(), cid))
        db.log(conn, user, 'contract', cid, action, {k: v for k, v in extra.items() if k not in ('terms_hash', 'verify_key')})
        conn.execute('commit')
    except BaseException:
        conn.execute('rollback')
        raise
    return get(conn, cid, user)


def find_by_key(conn, ref, key):
    """The contract a verify QR points to, or None. A wrong key looks exactly like a wrong reference."""
    c = conn.execute('select * from contracts where ref=?', (str(ref or '')[:20],)).fetchone()
    if not c or not c.get('verify_key') or not hmac.compare_digest(c['verify_key'].encode(), str(key or '').encode()):
        return None
    return c


def verify_status(c):
    """What a bank sees when it scans: valid only while it is signed and the terms still match both signatures."""
    if c['status'] != 'signed':
        return 'cancelled' if c['status'] in ('cancelled', 'declined') else 'not_signed'
    return 'valid' if c['terms_hash'] == terms_hash(c) else 'changed'

