"""Cashew nut photos a co-op adds so processors can see its nuts before they talk.

Photos are kept in SQLite. Phone photos carry hidden data (GPS location of the farm, camera, time), so every
upload is cleaned: JPEG APP1-APP15 and comment segments and PNG text/EXIF chunks are dropped before saving."""
import struct

import db

MAX_BYTES = 3_000_000
MAX_PER_COOP = 12
PNG_DROP = {b'eXIf', b'tEXt', b'zTXt', b'iTXt', b'tIME'}


def sniff(data):
    if data[:3] == b'\xff\xd8\xff':
        return 'image/jpeg'
    if data[:8] == b'\x89PNG\r\n\x1a\n':
        return 'image/png'
    raise ValueError('photo')


def strip_jpeg(data):
    """Copy a JPEG without its metadata segments (EXIF/GPS lives in APP1)."""
    out, i, n = bytearray(b'\xff\xd8'), 2, len(data)
    while i + 1 < n:
        if data[i] != 0xFF:
            raise ValueError('photo')
        marker = data[i + 1]
        if marker == 0xFF:                      # fill byte
            i += 1
            continue
        if marker == 0x01 or 0xD0 <= marker <= 0xD7:
            out += data[i:i + 2]
            i += 2
            continue
        if marker == 0xD9:
            return bytes(out + data[i:i + 2])
        if i + 4 > n:
            raise ValueError('photo')
        length = struct.unpack('>H', data[i + 2:i + 4])[0]
        if length < 2 or i + 2 + length > n:
            raise ValueError('photo')
        if marker == 0xDA:                      # start of scan: the rest is image data
            return bytes(out + data[i:])
        if not (0xE1 <= marker <= 0xEF or marker == 0xFE):
            out += data[i:i + 2 + length]
        i += 2 + length
    raise ValueError('photo')


def strip_png(data):
    out, i = bytearray(data[:8]), 8
    while i + 12 <= len(data):
        length = struct.unpack('>I', data[i:i + 4])[0]
        kind, end = data[i + 4:i + 8], i + 12 + length
        if end > len(data):
            raise ValueError('photo')
        if kind not in PNG_DROP:
            out += data[i:end]
        i = end
        if kind == b'IEND':
            return bytes(out)
    raise ValueError('photo')


def count(conn, coop_id):
    return conn.execute('select count(*) n from photos where coop_id=?', (coop_id,)).fetchone()['n']


def add(conn, coop_id, data, caption, user):
    if not data:
        raise ValueError('photo')
    if len(data) > MAX_BYTES:
        raise ValueError('too_large')
    mime = sniff(data)
    clean = strip_jpeg(data) if mime == 'image/jpeg' else strip_png(data)
    if count(conn, coop_id) >= MAX_PER_COOP:
        raise ValueError('too_many')
    caption = str(caption or '').strip()[:80]
    cur = conn.execute('insert into photos(coop_id, caption, mime, data, created_at, user_id) values(?,?,?,?,?,?)',
                       (coop_id, caption, mime, clean, db.now(), user['id']))
    return dict(id=cur.lastrowid, caption=caption, created_at=db.now())


def list_for(conn, coop_id):
    """Newest first, without the image bytes."""
    return conn.execute('select id, caption, created_at from photos where coop_id=? order by id desc', (coop_id,)).fetchall()


def get(conn, photo_id):
    row = conn.execute('select * from photos where id=?', (photo_id,)).fetchone()
    if not row:
        raise LookupError(photo_id)
    return row


def delete(conn, coop_id, photo_id):
    if not conn.execute('delete from photos where id=? and coop_id=?', (photo_id, coop_id)).rowcount:
        raise LookupError(photo_id)

