"""Non-blocking supply checks based on CDB and MAFF data."""

VARIETIES = {
    'M23': {'yield_t_ha': 2.08, 'nuts_per_kg': 120, 'kor': (28, 33), 'flowerings': '2-3'},
    'H09': {'yield_t_ha': 1.90, 'nuts_per_kg': 121, 'kor': (28, 32), 'flowerings': '1'},
    'M10': {'yield_t_ha': 1.81, 'nuts_per_kg': 118, 'kor': (29, 34), 'flowerings': '1'},
    'IM4': {'yield_t_ha': 1.80, 'nuts_per_kg': 123, 'kor': (27, 32), 'flowerings': '2'},
}


def _flag(code, level, scope, km, en, numbers, source):
    return {'code': code, 'level': level, 'scope': scope, 'msg_km': km,
            'msg_en': en, 'numbers': numbers, 'source': source}


def _reliable(commune):
    if not commune or commune.get('no_data') or commune.get('placeholder'):
        return False
    area, production = commune.get('planted_area_ha'), commune.get('production_t')
    return area is not None and production is not None and area > 0 and production > 0 and area != production


def member_flags(members, communes, districts, registry_row):
    flags = []
    areas = {}
    for member in members:
        code = member.get('cm_code')
        areas[code] = areas.get(code, 0) + (member.get('ha') or 0)
    maff_only = len(members) == 1 and members[0].get('id') == 0   # supply is the MAFF record, not a member list
    for code, area in areas.items():
        commune = communes.get(code)
        scope = f'commune:{code}'
        if not _reliable(commune):
            flags.append(_flag('no_data', 'grey', scope,
                'មិនមានទិន្នន័យឃុំដែលអាចទុកចិត្តបានទេ។',
                'No reliable commune data is available.', {}, 'CDB 2025'))
        elif area > commune['planted_area_ha'] and maff_only:
            flags.append(_flag('land', 'red', scope,
                'បញ្ជី MAFF បង្ហាញផ្ទៃដីស្វាយចន្ទីរបស់សហគមន៍នេះ ច្រើនជាងផ្ទៃដីស្វាយចន្ទីទាំងឃុំក្នុង CDB។ សូមពិនិត្យ។',
                'The MAFF list shows more cashew land for this co-op than CDB records for the whole commune. Please check.',
                {'cashew_ha': area, 'planted_area_ha': commune['planted_area_ha']}, 'MAFF cooperative registry / CDB 2025'))
        elif area > commune['planted_area_ha']:
            flags.append(_flag('land', 'red', scope,
                'ផ្ទៃដីសមាជិកលើសផ្ទៃដីដាំស្វាយចន្ទីក្នុងទិន្នន័យឃុំ។ សូមពិនិត្យ។',
                'Members’ area exceeds the commune’s recorded cashew area. Please check.',
                {'member_ha': area, 'planted_area_ha': commune['planted_area_ha']}, 'CDB 2025'))
    for member in members:
        ha, expected = member.get('ha'), member.get('expected_kg')
        if not ha or ha <= 0 or expected is None or expected == '':
            continue
        district = districts.get(member.get('ds_code')) or {}
        district_yield = district.get('yield_t_ha')
        variety = member.get('variety')
        variety_yield = VARIETIES.get(variety, {}).get('yield_t_ha')
        benchmarks = []
        if district_yield is not None and district_yield > 0:
            benchmarks.append((district_yield, 'district'))
        if variety_yield is not None:
            benchmarks.append((variety_yield, variety))
        if not benchmarks:
            continue
        benchmark, used = max(benchmarks, key=lambda item: item[0])
        actual = float(expected) / ha
        if actual > 1.3 * benchmark * 1000:
            flags.append(_flag('yield', 'amber', f"member:{member['id']}",
                'ទិន្នផលរំពឹងទុកខ្ពស់ជាងកម្រិតប្រៀបធៀប។ សូមពិនិត្យ។',
                'Expected yield is above the benchmark threshold. Please check.',
                {'expected_kg_per_ha': actual, 'benchmark_t_ha': benchmark,
                 'benchmark_used': used, 'threshold_kg_per_ha': 1.3 * benchmark * 1000},
                'CDB 2025 district yield / Cambodia Cashew Guide 2026, p. 13') | {'who': member.get('name') or ''})
    owing = sum(bool(member.get('owes_at_harvest')) for member in members)
    if owing:
        pct = 100 * owing / len(members)
        flags.append(_flag('harvest_debt', 'info', 'coop',
            'សមាជិកខ្លះមានកាតព្វកិច្ចសងនៅពេលប្រមូលផល ដែលអាចប៉ះពាល់ដល់ការលក់ជូនសហគមន៍។',
            'Some members owe at harvest, which may affect sales to the cooperative.',
            {'pct': pct, 'owing_members': owing, 'members': len(members)}, 'Member supply list'))
    if registry_row is None:
        flags.append(_flag('registry_missing', 'grey', 'coop',
            'រកមិនឃើញសហគមន៍ក្នុងបញ្ជី MAFF។',
            'Cooperative not found in the MAFF list.', {}, 'MAFF cooperative registry'))
    elif not registry_row.get('has_cashew'):
        flags.append(_flag('registry_no_cashew', 'info', 'coop',
            'បញ្ជី MAFF មិនបានបង្ហាញដំណាំស្វាយចន្ទីសម្រាប់សហគមន៍នេះទេ។',
            'The MAFF record does not list cashew for this cooperative.', {}, 'MAFF cooperative registry'))
    else:
        registry_ha = registry_row.get('cashew_ha')
        total_ha = sum(areas.values())
        if registry_ha is not None and total_ha > 1.5 * registry_ha:
            flags.append(_flag('registry_over', 'amber', 'coop',
                'ផ្ទៃដីស្វាយចន្ទីរបស់សមាជិកលើសទិន្នន័យរបស់សហគមន៍ក្នុងបញ្ជី MAFF។ សូមពិនិត្យ។',
                'Members’ cashew area exceeds the cooperative’s MAFF record. Please check.',
                {'member_ha': total_ha, 'cashew_ha': registry_ha, 'threshold_ha': 1.5 * registry_ha},
                'MAFF cooperative registry'))
    return flags


def verify(registry_row, communes):
    """The 2-step check on every co-op card: 1) is it in the MAFF list? 2) does its MAFF cashew land fit CDB?"""
    if registry_row is None:
        return {'maff': False, 'land': {'status': 'skip'}}
    ha = registry_row.get('cashew_ha')
    commune = communes.get(registry_row.get('cm_code'))
    land = {'status': 'no_cashew', 'maff_ha': ha}
    if registry_row.get('has_cashew') and ha:
        if not _reliable(commune):
            land['status'] = 'no_data'
        else:
            land.update(cdb_ha=commune['planted_area_ha'], status='over' if ha > commune['planted_area_ha'] else 'ok')
    return {'maff': True, 'land': land, 'source': 'MAFF cooperative registry / CDB 2025'}


def contract_flags(estimate_t, members, communes):
    codes = {member.get('cm_code') for member in members}
    reliable = [communes.get(code) for code in codes if _reliable(communes.get(code))]
    if not reliable:
        return []
    production = sum(commune['production_t'] for commune in reliable)
    if estimate_t > 0.5 * production:
        return [_flag('volume', 'amber', 'coop',
            'បរិមាណប៉ាន់ស្មានលើសពាក់កណ្ដាលនៃផលិតកម្មក្នុងទិន្នន័យឃុំ។ សូមពិនិត្យ។',
            'The estimate exceeds half of recorded production in the communes. Please check.',
            {'estimate_t': estimate_t, 'production_t': production,
             'share': 0.5, 'threshold_t': 0.5 * production}, 'CDB 2025')]
    return []

