"""CDB 2025 cashew figures by commune and district (read-only, from ../Data/CDB)."""
import csv
from functools import lru_cache
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / 'Data' / 'CDB'
YEAR = '2025'


def _num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0


def _rows(name):
    with (DATA / name).open(encoding='utf-8-sig', newline='') as f:
        return [r for r in csv.DictReader(f) if r['year'] == YEAR and r['pv_code'] != '00']


class Geo:
    def __init__(self):
        self.provinces, self.districts, self.communes = {}, {}, {}
        for r in _rows('cdb_cashew_district_2019_2025.csv'):
            self.provinces[r['pv_code']] = dict(code=r['pv_code'], name_en=r['province_en'], name_kh=r['province_kh'], parent='')
            y = r.get('avg_yield_t_ha_as_published')
            self.districts[r['ds_code']] = dict(code=r['ds_code'], name_en=r['district_en'], name_kh=r['district_kh'],
                                                pv_code=r['pv_code'], parent=r['pv_code'],
                                                yield_t_ha=_num(y) if y not in (None, '') else None)
        for r in _rows('cdb_cashew_commune_2023_2025.csv'):
            planted, prod = _num(r['planted_area_ha']), _num(r['production_t'])
            placeholder = planted > 0 and prod == planted
            self.communes[r['cm_code']] = dict(code=r['cm_code'], name_en=r['commune_en'], name_kh=r['commune_kh'],
                                               ds_code=r['ds_code'], pv_code=r['pv_code'], parent=r['ds_code'],
                                               planted_area_ha=planted, production_t=prod,
                                               placeholder=placeholder, no_data=planted <= 0 or placeholder)

    def commune(self, code):
        return self.communes.get(code)

    def district(self, code):
        return self.districts.get(code)

    def catalog(self):
        pick = lambda d: [dict(code=v['code'], name_en=v['name_en'], name_kh=v['name_kh'], parent=v['parent']) for v in d.values()]
        return dict(year=YEAR, source='https://cdb.nis.gov.kh', provinces=pick(self.provinces),
                    districts=pick(self.districts), communes=pick(self.communes))


@lru_cache(maxsize=1)
def load():
    return Geo()

