"""MAFF/DACP agricultural cooperative registry (acmaps.maff.gov.kh extract). No personal fields."""
import csv
import hashlib
from functools import lru_cache
from pathlib import Path

FILE = Path(__file__).resolve().parent.parent / 'Data' / 'Cooperatives' / 'dacp_acmaps.csv'
SOURCE = 'https://acmaps.maff.gov.kh'
_INVISIBLE = dict.fromkeys(map(ord, '​‌‍﻿'))


def norm_kh(s):
    return ' '.join(str(s or '').translate(_INVISIBLE).casefold().split())


def _int(v):
    try:
        return int(float(v))
    except (TypeError, ValueError):
        return None


def _float(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


@lru_cache(maxsize=1)
def rows():
    out = []
    with FILE.open(encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            key = '|'.join(r[k] for k in ('ac_name_kh', 'pv_code', 'ds_code', 'cm_code', 'lat', 'lng'))
            out.append(dict(
                ac_id=hashlib.sha1(key.encode()).hexdigest()[:10],
                name_kh=r['ac_name_kh'], province_kh=r['province_kh'], district_kh=r['district_kh'],
                commune_kh=r['commune_kh'], village_kh=r['village_kh'],
                pv_code=r['pv_code'], ds_code=r['ds_code'], cm_code=r['cm_code'],
                members_total=_int(r['members_total']), members_women=_int(r['members_women']),
                has_cashew=r['has_cashew'] == 'yes', cashew_ha=_float(r['cashew_ha']), cashew_t=_float(r['cashew_t']),
                year_view=r['year_view'], source=SOURCE))
    return tuple(out)


@lru_cache(maxsize=1)
def _index():
    return {r['ac_id']: r for r in rows()}


def get(ac_id):
    return _index().get(ac_id)


def search(q, limit=20):
    q = norm_kh(q).replace(' ', '')
    if not q:
        return []
    hits = []
    for r in rows():
        name = norm_kh(r['name_kh']).replace(' ', '')
        place = norm_kh(r['commune_kh'] + r['district_kh'] + r['province_kh']).replace(' ', '')
        if q in name:
            rank = 0 if name == q else 1
        elif q in place:
            rank = 2
        else:
            continue
        hits.append((rank, not r['has_cashew'], r['name_kh'], r))
    hits.sort(key=lambda h: h[:3])
    return [h[3] for h in hits[:limit]]
